<span class="line"><span class="__shiki_140thh">p1.</span><span class="__shiki_1t8gfj">then</span><span class="__shiki_140thh">(() </span><span class="__shiki_1itgoe">=&gt;</span><span class="__shiki_140thh"> console.</span><span class="__shiki_1t8gfj">log</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;p1.then() onResolved&quot;</span><span class="__shiki_140thh">));</span></span>
