<span class="line"><span class="__shiki_dzsirb">C</span><span class="__shiki_140thh">.</span><span class="__shiki_1t8gfj">then</span><span class="__shiki_140thh">(() </span><span class="__shiki_1itgoe">=&gt;</span><span class="__shiki_140thh"> console.</span><span class="__shiki_1t8gfj">log</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;G&quot;</span><span class="__shiki_140thh">));</span></span>
